292	    /** 查找序号最近的已打卡途经点：backward=true 向前，false 向后（仅限当前生效路线版本）。 */
293	    private Checkin nearestChecked(List<ApprovalWaypoint> waypoints, int seq, boolean backward) {
294	        ApprovalWaypoint result = null;
295	        for (ApprovalWaypoint w : waypoints) {
296	            if (backward ? (w.seq() < seq) : (w.seq() > seq)) {
297	                if (result == null
298	                        || (backward && w.seq() > result.seq())
299	                        || (!backward && w.seq() < result.seq())) {
300	                    result = w;
301	                }
302	            }
303	        }
304	        if (result == null) {
305	            return null;
306	        }
307	        return repository.findCheckin(result.shipmentId(), result.approvalId(), result.seq()).orElse(null);
308	    }
