310	    // ============================ 紧急改线 ============================
311	
312	    public ServiceResult reroute(String shipmentNo, RerouteRequest request) {
313	        String fingerprint = fingerprint("REROUTE", request.requestId(), shipmentNo, request.routeCode());
314	        return withIdempotency(request.requestId(), fingerprint,
315	                () -> tx.execute(status -> doReroute(shipmentNo, request)));
316	    }
317	
318	    private ServiceResult doReroute(String shipmentNo, RerouteRequest request) {
319	        Shipment shipment = loadShipment(shipmentNo);
320	        if (shipment.status().isTerminal()) {
321	            throw ApiException.conflict("SHIPMENT_TERMINAL", "运单已终态，不可改线");
322	        }
323	        if (shipment.status() != ShipmentStatus.DISPATCHED && shipment.status() != ShipmentStatus.IN_TRANSIT) {
324	            throw ApiException.conflict("INVALID_STATUS", "仅发运后可紧急改线，当前 " + shipment.status());
325	        }
326	        repository.findRoute(request.routeCode())
327	                .orElseThrow(() -> ApiException.badRequest("ROUTE_NOT_FOUND",
328	                        "路线不存在: " + request.routeCode()));
329	        List<RouteApproval> approvals = repository.findApprovals(shipment.id());
330	        boolean pendingExists = approvals.stream()
331	                .anyMatch(a -> a.status() == RouteApprovalStatus.PENDING);
332	        if (pendingExists) {
333	            throw ApiException.conflict("REROUTE_PENDING", "已有待核准改线申请，请先完成核准");
334	        }
335	        int nextVersion = approvals.stream().mapToInt(RouteApproval::versionNo).max().orElse(0) + 1;
336	        LocalDateTime now = now();
337	        long newApprovalId = repository.insertApproval(shipment.id(), request.routeCode(), nextVersion,
338	                RouteApprovalStatus.PENDING, null, now);
339	        List<RouteWaypointDef> defs = repository.findWaypointDefs(request.routeCode());
340	        for (RouteWaypointDef def : defs) {
341	            repository.insertWaypoint(newApprovalId, shipment.id(), def.seq(), def.name(),
342	                    shipment.plannedDeparture().plusMinutes(def.offsetMinutes()), WaypointState.PENDING);
343	        }
344	        Map<String, Object> body = shipmentView(shipmentNo);
345	        body.put("pendingApprovalId", newApprovalId);
346	        body.put("message", "改线申请已提交，核准通过前原路线打卡继续有效");
347	        return ServiceResult.ok(body);
348	    }
349	
350	    public ServiceResult approveReroute(String shipmentNo, long approvalId) {
351	        return tx.execute(status -> doApproveReroute(shipmentNo, approvalId));
352	    }
353	
354	    private ServiceResult doApproveReroute(String shipmentNo, long approvalId) {
355	        Shipment shipment = loadShipment(shipmentNo);
356	        RouteApproval next = repository.findApproval(approvalId)
357	                .orElseThrow(() -> ApiException.notFound("APPROVAL_NOT_FOUND", "核准记录不存在"));
358	        if (next.shipmentId() != shipment.id()) {
359	            throw ApiException.badRequest("APPROVAL_MISMATCH", "核准记录不属于该运单");
360	        }
361	        if (next.status() != RouteApprovalStatus.PENDING || next.versionNo() <= 1) {
362	            throw ApiException.conflict("APPROVAL_NOT_PENDING", "该记录不是待核准改线申请");
363	        }
364	        LocalDateTime now = now();
365	        RouteRuleEvaluator.Result result = evaluate(next.routeCode(),
366	                shipment.goodsCategory(), shipment.plannedDeparture());
367	        if (!result.allowed()) {
368	            // 改线驳回仅落库新记录的驳回结果，原路线继续有效；提交后返回 422。
369	            repository.updateApprovalStatus(next.id(), RouteApprovalStatus.REJECTED, now);
370	            repository.insertEvent(shipment.id(), EVT_REROUTE_REJECTED, result.message(), now);
371	            Map<String, Object> body = shipmentView(shipmentNo);
372	            body.put("errorCode", "REROUTE_REJECTED");
373	            body.put("message", result.message());
374	            return ServiceResult.status(422, body);
375	        }
376	        // 同一事务：旧路线终止 + 新路线生效 + 运单指向切换。
377	        RouteApproval old = currentApproval(shipment);
378	        repository.updateApprovalStatus(old.id(), RouteApprovalStatus.TERMINATED, now);
379	        repository.updateApprovalStatus(next.id(), RouteApprovalStatus.APPROVED, now);
380	        repository.updateCurrentApproval(shipment.id(), next.id());
381	        if (shipment.status() == ShipmentStatus.DISPATCHED) {
382	            repository.updateStatus(shipment.id(), ShipmentStatus.IN_TRANSIT);
383	        }
384	        repository.insertEvent(shipment.id(), EVT_REROUTE_SWITCH,
385	                "路线由 " + old.routeCode() + "(v" + old.versionNo() + ") 切换为 "
386	                        + next.routeCode() + "(v" + next.versionNo() + ")，原路线打卡保留", now);
387	        return ServiceResult.ok(shipmentView(shipmentNo));
388	    }
