593	    // ============================ 幂等支撑 ============================
594	
595	    /**
596	     * 以 requestId 幂等执行业务动作：
597	     * <ul>
598	     *   <li>同键同参：返回首次结果（成功或业务失败，含首次 HTTP 状态码）；</li>
599	     *   <li>同键异参：指纹不符返回 409；</li>
600	     *   <li>处理中并发：返回 409。</li>
601	     * </ul>
602	     */
603	    private ServiceResult withIdempotency(String requestId, String fingerprint,
604	                                          java.util.function.Supplier<ServiceResult> action) {
605	        for (int attempt = 0; attempt < 2; attempt++) {
606	            Optional<IdempotentRecord> existing = repository.findIdempotent(requestId);
607	            if (existing.isPresent()) {
608	                IdempotentRecord record = existing.get();
609	                if (!record.fingerprint().equals(fingerprint)) {
610	                    throw ApiException.conflict("IDEMPOTENT_FINGERPRINT_MISMATCH",
611	                            "requestId=" + requestId + " 已用于不同业务参数");
612	                }
613	                if ("COMPLETED".equals(record.status())) {
614	                    Map<String, Object> stored = parseJson(record.responseBody());
615	                    // 非 2xx 首次结果以相同状态码/错误码重放，保持 HTTP 语义一致。
616	                    if (record.httpStatus() != null && record.httpStatus() >= 400) {
617	                        Object code = stored.get("errorCode");
618	                        if (code == null) {
619	                            code = stored.get("code");
620	                        }
621	                        throw new ApiException(org.springframework.http.HttpStatus.valueOf(record.httpStatus()),
622	                                code == null ? "IDEMPOTENT_REPLAY" : code.toString(),
623	                                stored.get("message") == null ? "" : stored.get("message").toString());
624	                    }
625	                    return new ServiceResult(record.httpStatus(), stored);
626	                }
627	                throw ApiException.conflict("IDEMPOTENT_PROCESSING",
628	                        "相同 requestId 请求正在处理中");
629	            }
630	            boolean inserted = repository.insertProcessingIdempotent(requestId, fingerprint, now());
631	            if (!inserted) {
632	                continue; // 并发插入竞争：重读记录走重放分支
633	            }
634	            try {
635	                ServiceResult result = action.get();
636	                repository.completeIdempotent(requestId, result.httpStatus(), toJson(result.body()));
637	                return result;
638	            } catch (ApiException e) {
639	                Map<String, Object> errorBody = Map.of(
640	                        "code", e.getCode(),
641	                        "message", e.getMessage() == null ? "" : e.getMessage());
642	                repository.completeIdempotent(requestId, e.getStatus().value(), toJson(errorBody));
643	                throw e;
644	            } catch (RuntimeException e) {
645	                // 系统异常：保留 PROCESSING 之外，直接抛出（占位不删除，便于排查）。
646	                throw e;
647	            }
648	        }
649	        throw ApiException.conflict("IDEMPOTENT_RACE", "幂等记录并发竞争，请稍后重试");
650	    }
651	
652	    @SuppressWarnings("unchecked")
653	    private Map<String, Object> parseJson(String json) {
654	        if (json == null || json.isBlank()) {
655	            return Map.of();
656	        }
657	        try {
658	            return objectMapper.readValue(json, Map.class);
659	        } catch (JsonProcessingException e) {
660	            return Map.of("raw", json);
661	        }
662	    }
663	
664	    private String toJson(Map<String, Object> body) {
665	        try {
666	            return objectMapper.writeValueAsString(body);
667	        } catch (JsonProcessingException e) {
668	            throw new IllegalStateException("响应序列化失败", e);
669	        }
670	    }
671	
672	    private static String fingerprint(String operation, Object... parts) {
673	        StringBuilder sb = new StringBuilder(operation);
674	        for (Object part : parts) {
675	            sb.append('|').append(part);
676	        }
677	        try {
678	            MessageDigest digest = MessageDigest.getInstance("SHA-256");
679	            byte[] hash = digest.digest(sb.toString().getBytes(StandardCharsets.UTF_8));
680	            StringBuilder hex = new StringBuilder();
681	            for (byte b : hash) {
682	                hex.append(String.format("%02x", b));
683	            }
684	            return hex.toString();
685	        } catch (NoSuchAlgorithmException e) {
686	            throw new IllegalStateException(e);
687	        }
688	    }
689	}
