44	     * @param requiredLevel    危化品类别要求的最低通行等级
45	     * @param plannedDeparture 计划发运时刻
46	     * @param waypointDefs     路线途经点定义（按序号）
47	     * @param controlPeriods   该路线管制时段
48	     */
49	    public static Result evaluate(RouteInfo route, int requiredLevel, LocalDateTime plannedDeparture,
50	                                  List<RouteWaypointDef> waypointDefs, List<ControlPeriod> controlPeriods) {
51	        if (route.forbidden()) {
52	            return new Result(Verdict.FORBIDDEN_ROUTE, -1,
53	                    "路线 " + route.routeCode() + " 为禁行路线，禁止危化品运输");
54	        }
55	        if (route.passLevel() < requiredLevel) {
56	            return new Result(Verdict.LEVEL_MISMATCH, -1,
57	                    "路线 " + route.routeCode() + " 通行等级 " + route.passLevel()
58	                            + " 低于危化品要求等级 " + requiredLevel);
59	        }
60	        for (RouteWaypointDef def : waypointDefs) {
61	            LocalDateTime planned = plannedDeparture.plusMinutes(def.offsetMinutes());
62	            for (ControlPeriod period : controlPeriods) {
63	                if (inControlPeriod(planned, period)) {
64	                    return new Result(Verdict.CONTROL_PERIOD_CONFLICT, def.seq(),
65	                            "途经点 " + def.seq() + "(" + def.name() + ") 计划通过时刻 " + planned
66	                                    + " 落入管制时段 [" + period.startTime() + ", " + period.endTime() + ")");
67	                }
68	            }
69	        }
70	        return new Result(Verdict.ALLOWED, -1, "OK");
71	    }
72	
73	    /**
74	     * 半开区间判定：{@code start <= planned < end}。
75	     * 计划通过时刻恰等于起始时刻 → 受管制；恰等于结束时刻 → 不受管制。
76	     */
77	    public static boolean inControlPeriod(LocalDateTime planned, ControlPeriod period) {
78	        return !planned.isBefore(period.startTime()) && planned.isBefore(period.endTime());
79	    }
80	}
