package com.example.starter.hazmat.domain;

/**
 * 接力段状态机。
 *
 * <p>流转：IN_PROGRESS（进行中，等待双人打卡）→ COMPLETED（换班完成）；
 * 未按时完成换班被禁行冻结时为 FROZEN（随运单终态，不再接受打卡）。
 */
public enum RelaySegmentStatus {

    /** 进行中：已设置安全接力点，等待交接班双人打卡。 */
    IN_PROGRESS,
    /** 换班完成：双方打卡齐全且接班时刻严格晚于交班时刻、早于禁行起点。 */
    COMPLETED,
    /** 禁行冻结：未在夜间禁行起点前完成换班，随运单转处置。 */
    FROZEN
}

package com.example.starter.hazmat.domain;

/**
 * 接力打卡角色：交班（OUT）与接班（IN）。
 * 同一接力段每种角色仅一条打卡；双方编号须不同，单人打卡不生效。
 */
public enum EscortRole {

    /** 交班押运员：抵达接力点打卡交班。 */
    OUT,
    /** 接班押运员：打卡接续押运，时刻须严格晚于交班时刻。 */
    IN;

    /** 解析请求中的角色字符串，非法值返回 null 由调用方转 400。 */
    public static EscortRole parse(String value) {
        if (value == null) {
            return null;
        }
        try {
            return EscortRole.valueOf(value.trim().toUpperCase());
        } catch (IllegalArgumentException e) {
            return null;
        }
    }
}

