```java
/** 适用禁行规则：运输窗口（计划发运→最后途经点计划时刻）与禁行窗口相交则返回该规则，否则 null。 */
private NightCurfew applicableCurfew(Shipment shipment, List<ApprovalWaypoint> waypoints) {
    RouteApproval approval = currentApproval(shipment);
    List<NightCurfew> curfews = repository.findNightCurfews(approval.routeCode());
    if (curfews.isEmpty() || waypoints.isEmpty()) return null;
    LocalDateTime lastPlanned = waypoints.stream().map(ApprovalWaypoint::plannedTime).max(...).orElseThrow();
    for (NightCurfew c : curfews) {
        if (shipment.plannedDeparture().isBefore(c.curfewEnd()) && !lastPlanned.isBefore(c.curfewStart())) {
            return c;
        }
    }
    return null;
}
```

