    return jdbc.query("SELECT s." + SEGMENT_COLUMNS.replace(", ", ", s.") + " FROM relay_segment s "
                    + "JOIN shipment_active_relay a ON a.segment_id = s.id WHERE a.shipment_id = ?",
            SEGMENT_MAPPER, shipmentId).stream().findFirst();
}

